const coralArcherSheet=new Image();coralArcherSheet.assetSrc='assets/coral-archer-v2.png';let coralBolts=[];
function coralAimEnd(origin,angle){let end={x:origin.x,y:origin.y};for(let r=6;r<=600;r+=6){let q={x:origin.x+Math.cos(angle)*r,y:origin.y+Math.sin(angle)*r};if(!passable(q.x,q.y,8)||!lineClear(end,q,8))break;end=q;}return end;}
function beginCoralArcher(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'coralReaimBurst',bespoke:true,windup:1,origin:{x:e.x,y:e.y},angles:[angle,null,null],ends:[coralAimEnd(e,angle),null,null],fired:[false,false,false]};e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;}
function coralBoltContact(point,start,end){let dx=end.x-start.x,dy=end.y-start.y,d2=dx*dx+dy*dy;if(d2<1e-10)return null;let t=Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/d2)),q={x:start.x+dx*t,y:start.y+dy*t};return dist(point,q)<=12+1e-8?q:null;}
function stepCoralBolt(b,dt){let start={x:b.x,y:b.y},travel=Math.max(0,Math.min(600-b.travel,dt*520)),n=Math.max(1,Math.ceil(travel/6)),end={...start},blocked=false;for(let i=1;i<=n;i++){let q={x:start.x+b.ux*travel*i/n,y:start.y+b.uy*travel*i/n};if(!passable(q.x,q.y,8)||!lineClear(end,q,8)){blocked=true;break;}end=q;}b.x=end.x;b.y=end.y;b.travel+=dist(start,end);let contact=coralBoltContact(p,start,end);if(!(p.inv>0)&&contact&&lineClear(contact,p)){hurt(46);return false;}return !blocked&&b.travel<600-1e-8;}
function advanceCoralBolts(dt,skipFresh=false){if(!started||paused||dead||!Number.isFinite(dt)||dt<=0)return;coralBolts=coralBolts.filter(b=>b.owner===p&&(skipFresh&&b.spawnClock===clock||!dead&&stepCoralBolt(b,dt)));}
const coralArcherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e3')return coralArcherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='coralReaimBurst'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=440&&clear){beginCoralArcher(e);return;}e.state='idle';if(d>800&&!e.aware||d<=300&&clear)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,86*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,16)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 for(let [i,lock,fire]of [[0,0,1],[1,1.2,1.65],[2,1.85,2.3]]){if(dead)break;if(a.angles[i]===null&&e.elapsed>=lock){a.angles[i]=Math.atan2(p.y-e.y,p.x-e.x);a.ends[i]=coralAimEnd(a.origin,a.angles[i]);a.windup=fire;e.struck=false;e.facing=Math.cos(a.angles[i])-Math.sin(a.angles[i])<0?-1:1;}if(!a.fired[i]&&e.elapsed>=fire){a.fired[i]=true;e.struck=true;let b={owner:p,x:e.x,y:e.y,ux:Math.cos(a.angles[i]),uy:Math.sin(a.angles[i]),travel:0,spawnClock:clock};if(stepCoralBolt(b,e.elapsed-fire))coralBolts.push(b);playSound('arrow',e.x,e.y);}}if(e.elapsed>=3){e.attack=null;e.state='idle';e.t=2.8;}
};
const coralArcherUpdateBase=update;update=dt=>{let active=started&&!paused&&!dead;coralArcherUpdateBase(dt);if(active)advanceCoralBolts(dt,true);};
const coralArcherResetBase=resetWorld;resetWorld=()=>{coralBolts=[];return coralArcherResetBase();};const coralArcherLoadBase=loadWorld;loadWorld=(...args)=>{coralBolts=[];return coralArcherLoadBase(...args);};
const coralArcherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e3'||!coralArcherSheet.complete||!coralArcherSheet.naturalWidth||!coralArcherSheet.naturalHeight)return coralArcherDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='coralReaimBurst')f={row:2,col:e.elapsed<.4?0:[1,1.65,2.3].some(t=>e.elapsed>=t&&e.elapsed<t+.16)?2:e.elapsed<2.3?1:3};let q=project(e.x,e.y),sw=coralArcherSheet.naturalWidth/4,sh=coralArcherSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=[.91,.92,.92][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,coralArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(coralArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const coralArcherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e3'?140:coralArcherSizeBase(e);
const coralArcherGroundBase=drawGroundEffects;drawGroundEffects=()=>{coralArcherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e3'):enemies)){let a=e.attack;if(e.species!=='r8e3'||e.hp<=0||a?.pattern!=='coralReaimBurst'||!visibleAt(e.x,e.y))continue;let i=a.angles.findIndex((angle,j)=>angle!==null&&!a.fired[j]);if(i<0)continue;let end=a.ends[i];let start=project(e.x,e.y),finish=project(end.x,end.y);ctx.save();ctx.strokeStyle=['#e7c990','#dfb4a4','#d8a8c9'][i];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(finish.x,finish.y);ctx.stroke();ctx.restore();}};
const coralArcherEffectsBase=drawEffects;drawEffects=()=>{coralArcherEffectsBase();ctx.save();ctx.strokeStyle='#f2ccb0';ctx.lineWidth=3;for(let b of coralBolts){if(b.owner!==p||!visibleAt(b.x,b.y))continue;let q=project(b.x,b.y),tail=project(b.x-b.ux*22,b.y-b.uy*22);ctx.beginPath();ctx.moveTo(tail.x,tail.y-16);ctx.lineTo(q.x,q.y-16);ctx.stroke();}ctx.restore();};
